-- migrate:up
-- News items of the general-public newsletter (lot 14 a of druid-internal docs/plan-migration-postgresql.md, D10
-- revised on 2026-10-12): generated by Druid from the OpenAlex articles of a structure (POST /api/newsletter/generate),
-- then edited in the Newsletter panel (status, brief, validation). Formerly the Grist table `Newsletter`
-- (scripts/import_newsletter.ts; the items get new ids, no id of a news item being kept anywhere).
CREATE TABLE newsletter_item (
  id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug             text NOT NULL,
  -- OpenAlex work (W…): a work is never generated twice for a structure.
  work_id          text NOT NULL,
  -- Issue of the newsletter (YYYY-MM of the generation).
  numero           text NOT NULL DEFAULT '',
  titre            text NOT NULL DEFAULT '',
  doi              text NOT NULL DEFAULT '',
  -- As OpenAlex gives it (YYYY-MM-DD, sometimes less precise).
  date_publication text NOT NULL DEFAULT '',
  journal          text NOT NULL DEFAULT '',
  auteurs          text NOT NULL DEFAULT '',
  labs             text NOT NULL DEFAULT '',
  accroche         text NOT NULL DEFAULT '',
  resume           text NOT NULL DEFAULT '',
  -- Raw answer of the language model, kept for review.
  resume_genere    text NOT NULL DEFAULT '',
  statut           text NOT NULL DEFAULT 'genere' CHECK (statut IN ('genere', 'envoye', 'valide', 'rejete', 'publie')),
  chercheur_nom    text NOT NULL DEFAULT '',
  chercheur_email  text NOT NULL DEFAULT '',
  chercheur_photo  text NOT NULL DEFAULT '',
  chercheur_url    text NOT NULL DEFAULT '',
  genere_le        timestamptz,
  valide_le        timestamptz,
  valide_par       text NOT NULL DEFAULT '',
  commentaire      text NOT NULL DEFAULT '',
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (slug, work_id)
);
CREATE TRIGGER newsletter_item_updated_at BEFORE UPDATE ON newsletter_item FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER newsletter_item_audit AFTER INSERT OR UPDATE OR DELETE ON newsletter_item FOR EACH ROW EXECUTE FUNCTION audit_row();

-- migrate:down
DROP TABLE newsletter_item;
